-- Two-factor authentication (TOTP, RFC 6238) for web interface users.
-- Secrets are encrypted with the master key (context "user:<id>:totp").
ALTER TABLE users ADD COLUMN totp_secret_enc  TEXT NOT NULL DEFAULT '';
-- Secret generated by the set-up step, waiting for a first valid code.
ALTER TABLE users ADD COLUMN totp_pending_enc TEXT NOT NULL DEFAULT '';
-- Last accepted time step: a code cannot be replayed.
ALTER TABLE users ADD COLUMN totp_last_step   INTEGER NOT NULL DEFAULT 0;
-- JSON array of SHA-256 hashes of the unused recovery codes.
ALTER TABLE users ADD COLUMN totp_recovery    TEXT NOT NULL DEFAULT '[]';
